-- ------------------------------------------------------------------ data builders
-- rewards: { money, gold, points (the server's extra currency), xp }

local function skin(model, name, loot, rewards, deletePelt)
    return { model = model, name = name, loot = loot, reward = rewards, deletePelt = deletePelt == true }
end

local function buy(model, name, rewards, loot, quality, factor)
    return {
        model = model, name = name, reward = rewards, loot = loot,
        quality = { poor = quality[1], good = quality[2], perfect = quality[3] },
        factor  = { poor = factor[1],  good = factor[2],  perfect = factor[3]  },
    }
end

local function butcher(name, job, at, heading, radius, ped, blip)
    return { name = name, job = job, at = at, heading = heading, radius = radius, ped = ped, blip = blip }
end

